<?php\n/**\n * ══════════════════════════════════════════════════════════════\n * CONFIGURAÇÃO DE BANCO DE DADOS - PREFEITURA VARGEM GRANDE\n * ══════════════════════════════════════════════════════════════\n */\n\n// Credenciais MySQL\ndefine('DB_HOST', 'localhost');\ndefine('DB_USER', 'root');                    // Seu usuário MySQL\ndefine('DB_PASS', '');                        // Sua senha MySQL (deixe vazio se não houver)\ndefine('DB_NAME', 'prefeitura_vgrp');         // Nome do banco\ndefine('DB_CHARSET', 'utf8mb4');\n\n// Configuração\ndefine('DEBUG_MODE', true);                   // true em desenvolvimento, false em produção\ndefine('CORS_ENABLED', true);                 // Permitir requisições cross-origin\n\n// Conectar ao banco\ntry {\n    $pdo = new PDO(\n        'mysql:host=' . DB_HOST . ';dbname=' . DB_NAME . ';charset=' . DB_CHARSET,\n        DB_USER,\n        DB_PASS,\n        [\n            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\n            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\n            PDO::ATTR_EMULATE_PREPARES => false,\n        ]\n    );\n} catch (PDOException $e) {\n    http_response_code(500);\n    echo json_encode(['erro' => 'Erro ao conectar ao banco de dados', 'mensagem' => $e->getMessage()]);\n    exit;\n}\n\n// Headers CORS\nif (CORS_ENABLED) {\n    header('Access-Control-Allow-Origin: *');\n    header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS');\n    header('Access-Control-Allow-Headers: Content-Type, Authorization');\n    header('Content-Type: application/json; charset=utf-8');\n}\n\n// Função para log de erros\nfunction logErro($mensagem, $dados = []) {\n    if (DEBUG_MODE) {\n        $log = date('Y-m-d H:i:s') . ' - ' . $mensagem . ' ' . json_encode($dados) . \"\\n\";\n        file_put_contents(__DIR__ . '/logs/erros.log', $log, FILE_APPEND);\n    }\n}\n\n// Função para resposta JSON\nfunction resposta($sucesso, $dados, $mensagem = '') {\n    return json_encode([\n        'sucesso' => $sucesso,\n        'dados' => $dados,\n        'mensagem' => $mensagem\n    ]);\n}\n\n?>\n